import {
  DashboardListView,
  DashboardListViewHeader,
  DashboardListViewHeaderTitle,
  DashboardListViewHeaderMetadata,
  DashboardListViewItems,
  DashboardListItem,
  DashboardListItemTitle,
  DashboardListViewItemsSkeletonLoader,
} from './DashboardListView'
import {useQueries} from '@github-ui/react-query'
import {useClickAnalytics, useAnalytics} from '@github-ui/use-analytics'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useCallback, useMemo} from 'react'
import type {DashboardPullRequest} from '../types'
import {QueryQualifier, DashboardPullRequestValidator} from '../types'
import {dashboardLocalStorage, useDashboardStorage} from '../utils/dashboard-local-storage'
import {dedupeById} from '../utils/dedupe-by-id'
import {ListActionMenu} from './ListActionMenu'
import {PullRequestListItem} from './PullRequestListItem'
import {AlertIcon} from '@primer/octicons-react'
import {Link, Stack} from '@primer/react'
import styles from './DashboardListView.module.css'
import {useLocalStorageCache} from '../hooks/useLocalStorageCache'
import {createPersister} from '@github-ui/react-query-persister'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {ONE_MIN} from '../constants'

interface PullRequestsListProps {
  userDisplayLogin: string
  loadingState?: React.ReactElement
  showCopilotChatActions?: boolean
}

const DEFAULT_RESULT_COUNT = 3
const DEFAULT_QUERY_QUALIFIERS = [
  QueryQualifier.Authored,
  QueryQualifier.Mentions,
  QueryQualifier.ReviewRequested,
  QueryQualifier.ReviewedBy,
]
const DEFAULT_LOADING_STATE = <DashboardListViewItemsSkeletonLoader />

const noop = () => undefined

export function PullRequestsList({
  userDisplayLogin,
  loadingState = DEFAULT_LOADING_STATE,
  showCopilotChatActions,
}: PullRequestsListProps) {
  const {data} = useDashboardStorage()
  const queryQualifiers = data?.pullRequestQueryQualifiers ?? DEFAULT_QUERY_QUALIFIERS
  const resultCount = data?.pullRequestResultCount ?? DEFAULT_RESULT_COUNT
  const {sendAnalyticsEvent} = useAnalytics()
  const dashboard_indexeddb_caching = isFeatureEnabled('dashboard_indexeddb_caching')
  const {getLocalStorageValue, setLocalStorageValue: _setLocalStorageValue} =
    useLocalStorageCache<DashboardPullRequest[]>('dashboard-pullrequests')
  // When feature flag is off, use localStorage
  const setLocalStorageValue = dashboard_indexeddb_caching ? noop : _setLocalStorageValue
  // eslint-disable-next-line react-hooks/purity -- using a memo to lock in the value
  const now = useMemo(() => Date.now(), [])

  const setPullRequestQueryQualifiers = (queries: QueryQualifier[]) => {
    dashboardLocalStorage.setPullRequestQueryQualifiers(queries)
  }

  const setPullRequestResultCount = (count: number) => {
    dashboardLocalStorage.setPullRequestResultCount(count)
  }

  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const onViewAllPulls = useCallback(() => {
    sendClickAnalyticsEvent({category: 'productivity_dashboard', action: 'click.view_all_pulls'})
  }, [sendClickAnalyticsEvent])
  const onTitleClick = useCallback(() => {
    sendClickAnalyticsEvent({category: 'productivity_dashboard', action: 'click.navigate_to_pr'})
  }, [sendClickAnalyticsEvent])
  const baseQuery = 'is:pr is:open archived:false sort:updated-desc'

  const persister = useMemo(
    () =>
      createPersister({
        validator: DashboardPullRequestValidator,
        sendAnalyticsEvent,
        enabled: dashboard_indexeddb_caching,
      }),
    [sendAnalyticsEvent, dashboard_indexeddb_caching],
  )

  const {
    isLoading,
    data: pullRequests,
    isError,
  } = useQueries({
    queries: queryQualifiers.map(qualifier => {
      const queryKey = [baseQuery, qualifier, userDisplayLogin]
      const localCacheKey = queryKey.join('::')
      return {
        queryKey,
        queryFn: async () => {
          const response = await reactFetchJSON(
            `/productivity_dashboard/pulls?q=${encodeURIComponent(`${baseQuery} ${qualifier}:${userDisplayLogin}`)}`,
          )

          if (!response.ok) throw new Error(`HTTP ${response.status}`)

          const payload = (await response.json()).data as DashboardPullRequest[]
          setLocalStorageValue(localCacheKey, payload)
          return payload
        },
        staleTime: ONE_MIN,
        persister,
        initialData: dashboard_indexeddb_caching ? undefined : () => getLocalStorageValue(localCacheKey),
        initialDataUpdatedAt: dashboard_indexeddb_caching ? undefined : now - ONE_MIN, // triggers refetch immediately
      }
    }),
    combine: results => {
      return {
        data: dedupeById(results.flatMap(result => result.data || []))
          .sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
          .slice(0, resultCount),
        isLoading: results.some(result => result.isLoading),
        isError: results.some(result => result.isError),
      }
    },
  })

  return (
    <DashboardListView>
      <DashboardListViewHeader>
        <DashboardListViewHeaderTitle headingLevel="h3">
          <Stack direction="horizontal" gap="condensed" align="center">
            Pull requests
          </Stack>
        </DashboardListViewHeaderTitle>
        <DashboardListViewHeaderMetadata>
          <Link href="/pulls" onClick={onViewAllPulls}>
            View all
          </Link>
          <ListActionMenu
            setQueryQualifiers={setPullRequestQueryQualifiers}
            queryQualifiers={queryQualifiers}
            setResultCount={setPullRequestResultCount}
            resultCount={resultCount}
            label="Pull request options"
            filterGroupHeading="Pull requests to include"
            menuItems={[
              {label: 'Authored', value: QueryQualifier.Authored},
              {label: 'Mentioned', value: QueryQualifier.Mentions},
              {label: 'Review requested', value: QueryQualifier.ReviewRequested},
              {label: 'Reviewed', value: QueryQualifier.ReviewedBy},
            ]}
            analyticsEventType={'pull_request_options.save'}
            analyticsTarget={'DASHBOARD_PULL_REQUEST_ACTION_MENU'}
            analyticsCategory="productivity_dashboard"
          />
        </DashboardListViewHeaderMetadata>
      </DashboardListViewHeader>
      <DashboardListViewItems>
        {isError ? (
          <DashboardListItem className={styles.emptyItem}>
            <AlertIcon className={styles.noItemsIcon} />

            <DashboardListItemTitle as="p" className={styles.emptyTitle}>
              Unable to load pull requests, try again later.
            </DashboardListItemTitle>
          </DashboardListItem>
        ) : isLoading ? (
          loadingState
        ) : pullRequests.length === 0 ? (
          <DashboardListItem className={styles.emptyItem}>
            <DashboardListItemTitle as="p" className={styles.emptyTitle}>
              No pull requests found, try a different filter.
            </DashboardListItemTitle>
          </DashboardListItem>
        ) : (
          pullRequests.map(pullRequest => (
            <PullRequestListItem
              key={pullRequest.id}
              pullRequest={pullRequest}
              onTitleClick={onTitleClick}
              showCopilotChatActions={showCopilotChatActions}
            />
          ))
        )}
      </DashboardListViewItems>
    </DashboardListView>
  )
}

try{ PullRequestsList.displayName ||= 'PullRequestsList' } catch {}