// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {COPILOT_PATH} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import type {
  CopilotChatRepo,
  IssueReference,
  PullRequestReference,
  // eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
} from '@github-ui/copilot-chat/utils/copilot-chat-types'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useCallback} from 'react'
import type {DashboardIssue, DashboardPullRequest} from '../types'

export function useOpenCopilotChat() {
  const openCopilotChat = useCallback((reference: PullRequestReference | IssueReference, sourceElementId: string) => {
    const threadID = null // start a new thread

    copilotLocalStorage.setCurrentReferences(threadID, [reference])

    sendEvent('copilot.open_copilot_chat', {source: `element ${sourceElementId}`})

    window.location.href = COPILOT_PATH
  }, [])

  const openCopilotChatWithPullRequest = useCallback(
    (pullRequest: DashboardPullRequest, sourceElementId: string) => {
      const reference = createPullRequestReference(pullRequest)
      openCopilotChat(reference, sourceElementId)
    },
    [openCopilotChat],
  )

  const openCopilotChatWithIssue = useCallback(
    (issue: DashboardIssue, sourceElementId: string) => {
      const reference = createIssueReference(issue)
      openCopilotChat(reference, sourceElementId)
    },
    [openCopilotChat],
  )

  return {openCopilotChatWithIssue, openCopilotChatWithPullRequest}
}

function createPullRequestReference(pullRequest: DashboardPullRequest): PullRequestReference {
  return {
    type: 'pull-request',
    title: pullRequest.title,
    id: Number(pullRequest.id),
    number: pullRequest.number,
    url: pullRequest.permalink,
    authorLogin: pullRequest.author,
    repository: createPullRequestRepositoryReference(pullRequest),
  }
}

function createIssueReference(issue: DashboardIssue): IssueReference {
  return {
    type: 'issue',
    title: issue.title,
    id: Number(issue.id),
    number: issue.number,
    repository: {
      id: Number(issue.repository.id),
      name: issue.repository.name,
      owner: issue.repository.ownerLogin,
    },
    url: issue.permalink,
  }
}

function createPullRequestRepositoryReference(pullRequest: DashboardPullRequest): CopilotChatRepo {
  const repository = pullRequest.repository
  return {
    id: repository.id,
    name: repository.name,
    ownerLogin: repository.ownerLogin,
    ownerType: repository.isOrgOwned ? 'Organization' : 'User',
    ownerAvatarUrl: repository.ownerAvatar,
    commitOID: pullRequest.headSha,
    ref: repository.defaultBranch,
    refInfo: {
      name: repository.defaultBranch,
      type: 'branch',
    },
    visibility: repository.public ? 'PUBLIC' : repository.private ? 'PRIVATE' : 'INTERNAL',
    defaultBranch: repository.defaultBranch,
  }
}
